using UnityEngine;
using UnityEngine.Tilemaps;
using Framework.Grid;
using Framework.Tilemap;

namespace Game.Tests
{
    /// <summary>
    /// 汎用Tilemapレンダラーの動作確認用クラス。
    /// </summary>
    public class GridTilemapRendererTest : MonoBehaviour
    {
        #region Fields

        [Header("マップ設定")]

        /// <summary>マップの横方向のマス数。</summary>
        [SerializeField]
        [Min(3)]
        [Tooltip("マップの横方向のマス数")]
        private int width = 15;

        /// <summary>マップの縦方向のマス数。</summary>
        [SerializeField]
        [Min(3)]
        [Tooltip("マップの縦方向のマス数")]
        private int height = 11;

        [Header("Tilemap設定")]

        /// <summary>床を描画するTilemap。</summary>
        [SerializeField]
        [Tooltip("床を描画するTilemap")]
        private Tilemap floorTilemap;

        /// <summary>壁を描画するTilemap。</summary>
        [SerializeField]
        [Tooltip("壁を描画するTilemap")]
        private Tilemap wallTilemap;

        [Header("タイル設定")]

        /// <summary>床として使用するタイル。</summary>
        [SerializeField]
        [Tooltip("床として使用するTileアセット")]
        private TileBase floorTile;

        /// <summary>壁として使用するタイル。</summary>
        [SerializeField]
        [Tooltip("壁として使用するTileアセット")]
        private TileBase wallTile;

        [Header("テスト設定")]

        /// <summary>壁の切り替えテストを行うマス。</summary>
        [SerializeField]
        [Tooltip("壁の生成・消去を確認するマスの座標")]
        private Vector2Int testPosition =
            new Vector2Int(1, 1);

        /// <summary>床を表すマスデータ。</summary>
        private const int Floor = 0;

        /// <summary>壁を表すマスデータ。</summary>
        private const int Wall = 1;

        /// <summary>動作確認用のマップデータ。</summary>
        private GridMap<int> map;

        /// <summary>動作確認用のTilemapレンダラー。</summary>
        private GridTilemapRenderer<int> mapRenderer;

        #endregion

        #region Unity Methods

        /// <summary>
        /// マップ生成と初期描画を実行する。
        /// </summary>
        private void Start()
        {
            if (!ValidateSettings())
            {
                return;
            }

            CreateMap();

            CreateRenderer();

            mapRenderer.RenderAll();

            Debug.Log(
                $"マップ描画完了：{map.Width} × {map.Height}\n" +
                $"登録レイヤー数：{mapRenderer.LayerCount}",
                this);
        }

        /// <summary>
        /// コンポーネント破棄時の終了処理。
        /// </summary>
        private void OnDestroy()
        {
            // イベント登録と内部参照を解除する。
            mapRenderer?.Dispose();

            mapRenderer = null;
        }

        #endregion

        #region Initialization

        /// <summary>
        /// Inspectorの設定内容が有効か確認する。
        /// </summary>
        /// <returns>設定が有効な場合はtrue</returns>
        private bool ValidateSettings()
        {
            if (floorTilemap == null || wallTilemap == null)
            {
                Debug.LogError(
                    "Tilemapが設定されていません。",
                    this);

                return false;
            }

            if (floorTilemap == wallTilemap)
            {
                Debug.LogError(
                    "床と壁には異なるTilemapを指定してください。",
                    this);

                return false;
            }

            if (floorTile == null || wallTile == null)
            {
                Debug.LogError(
                    "床または壁のタイルが設定されていません。",
                    this);

                return false;
            }

            return true;
        }

        /// <summary>
        /// 外周と内部の一部に壁を持つマップを生成する。
        /// </summary>
        private void CreateMap()
        {
            map = new GridMap<int>(
                width,
                height,
                position =>
                {
                    // マップの外周に位置するか判定する。
                    bool isBorder =
                        position.x == 0 ||
                        position.y == 0 ||
                        position.x == width - 1 ||
                        position.y == height - 1;

                    // 外周は壁として設定する。
                    if (isBorder)
                    {
                        return Wall;
                    }

                    // 内部に一定間隔で壁を配置する。
                    bool isInnerWall =
                        position.x % 2 == 0 &&
                        position.y % 2 == 0;

                    return isInnerWall ? Wall : Floor;
                });
        }

        /// <summary>
        /// 描画システムを生成してレイヤーを登録する。
        /// </summary>
        private void CreateRenderer()
        {
            // 自動更新を有効にしてレンダラーを生成する。
            mapRenderer =
                new GridTilemapRenderer<int>(map, true);

            // 床はすべてのマスに描画する。
            mapRenderer.AddLayer(
                floorTilemap,
                (position, cellData) => floorTile);

            // 壁は壁データを持つマスにだけ描画する。
            mapRenderer.AddLayer(
                wallTilemap,
                (position, cellData) =>
                    cellData == Wall ? wallTile : null);
        }

        #endregion

        #region Test Methods

        /// <summary>
        /// 指定されたマスの床と壁を切り替える。
        /// マップ変更時の自動描画を確認するために使用する。
        /// </summary>
        [ContextMenu("テスト/指定マスの壁を切り替える")]
        public void ToggleTestCell()
        {
            if (map == null)
            {
                Debug.LogWarning(
                    "再生モードで実行してください。",
                    this);

                return;
            }

            // 現在のマスデータを取得する。
            if (!map.TryGetCell(
                testPosition,
                out int currentValue))
            {
                Debug.LogWarning(
                    "テスト座標がマップの範囲外です。",
                    this);

                return;
            }

            // 床と壁を切り替える。
            int newValue =
                currentValue == Wall ? Floor : Wall;

            // マップデータを変更する。
            // 描画はCellChangedイベントによって更新される。
            map.SetCell(testPosition, newValue);

            Debug.Log(
                $"マス変更：{testPosition}\n" +
                $"{currentValue} → {newValue}",
                this);
        }

        /// <summary>
        /// マップ全体を再描画する。
        /// </summary>
        [ContextMenu("テスト/マップを再描画する")]
        public void RedrawMap()
        {
            if (mapRenderer == null)
            {
                return;
            }

            mapRenderer.RenderAll();

            Debug.Log("マップを再描画しました。", this);
        }

        /// <summary>
        /// マップの描画内容を消去する。
        /// マップデータ自体は変更しない。
        /// </summary>
        [ContextMenu("テスト/マップの描画を消去する")]
        public void ClearMap()
        {
            if (mapRenderer == null)
            {
                return;
            }

            mapRenderer.Clear();

            Debug.Log("マップの描画を消去しました。", this);
        }

        #endregion
    }
}
